// Interactive two-way converter used by every /converters/ page.
// Markup is generated by scripts/converters.mjs; all maths is in convert-engine.js.
import { UNITS, convert, feetInchesToCm, cmToFeetInches, formatNumber } from "./convert-engine.js";

const DIGITS = 6;
const show = v => formatNumber(v, DIGITS);
const num = s => {
  const t = String(s).trim().replace(",", ".");
  return t === "" ? NaN : Number(t);
};

function linear(box) {
  const a = box.querySelector("[data-side=a]"), b = box.querySelector("[data-side=b]");
  const unitA = box.dataset.from, select = box.querySelector("select[data-unit-b]");
  const out = box.querySelector("[data-result]");
  const unitB = () => (select ? select.value : box.dataset.to);
  const sentence = (va, vb) => {
    if (!out) return;
    out.textContent = Number.isFinite(va) && Number.isFinite(vb)
      ? `${show(va)} ${UNITS[unitA].symbol} = ${show(vb)} ${UNITS[unitB()].symbol}` : "Enter a number to convert.";
  };
  const fromA = () => { const v = num(a.value); const r = convert(v, unitA, unitB()); b.value = Number.isFinite(r) ? show(r).replace(/,/g, "") : ""; sentence(v, r); };
  const fromB = () => { const v = num(b.value); const r = convert(v, unitB(), unitA); a.value = Number.isFinite(r) ? show(r).replace(/,/g, "") : ""; sentence(r, v); };
  a.addEventListener("input", fromA);
  b.addEventListener("input", fromB);
  if (select) select.addEventListener("change", () => {
    fromA();
    box.querySelectorAll("[data-unit-label]").forEach(el => { el.textContent = UNITS[unitB()].symbol; });
  });
  fromA();
}

function height(box) {
  const ft = box.querySelector("[data-side=ft]"), inch = box.querySelector("[data-side=in]"), cm = box.querySelector("[data-side=cm]");
  const out = box.querySelector("[data-result]");
  const sentence = (f, i, c) => {
    out.textContent = Number.isFinite(c) ? `${show(f)} ft ${show(i)} in = ${show(c)} cm` : "Enter a height to convert.";
  };
  const fromFtIn = () => {
    const f = num(ft.value || 0), i = num(inch.value || 0);
    if (!Number.isFinite(f) || !Number.isFinite(i)) { cm.value = ""; sentence(f, i, NaN); return; }
    const c = feetInchesToCm(f, i); cm.value = show(c).replace(/,/g, ""); sentence(f, i, c);
  };
  const fromCm = () => {
    const c = num(cm.value);
    if (!Number.isFinite(c)) { sentence(0, 0, NaN); return; }
    const h = cmToFeetInches(c); ft.value = String(h.feet); inch.value = formatNumber(h.inches, 2); sentence(h.feet, Number(formatNumber(h.inches, 2)), c);
  };
  ft.addEventListener("input", fromFtIn); inch.addEventListener("input", fromFtIn); cm.addEventListener("input", fromCm);
  fromFtIn();
}

document.querySelectorAll("[data-converter]").forEach(box => (box.dataset.converter === "height" ? height(box) : linear(box)));
